update public.centers c set
  agencies = coalesce(u.a, c.agencies), agency_detail = coalesce(u.d, c.agency_detail),
  website = coalesce(u.w, c.website), phone = coalesce(u.p, c.phone), locality = coalesce(u.l, c.locality),
  directory_check = case when u.s in ('ok', 'unsure') then u.s else c.directory_check end,
  checked_at = date '2026-10-17',
  listing_status = case when u.s = 'closed' or u.x = 1 then 'cerrado' else c.listing_status end
from u where c.id = u.i and c.listing_status = 'directorio';

insert into public.centers (name, destination, area, province, locality, website, phone, source_url, agencies, agency_detail,
                            listing_status, verification_status, directory_check, checked_at, lat, lng, location_precision)
select n.n, n.t, n.t, coalesce(n.v, d.province), n.l, n.w, n.p, n.u, coalesce(n.a, '{}'), n.d,
       'directorio', 'unverified', 'ok', date '2026-10-17', d.lat, d.lng, 'zona'
